public class SolutionTest {
    public static void main(String[] args) {
        assertEquals("0", Solution.fold(nullSafeEmpty()));
        assertEquals("0", Solution.fold("   \t\n "));
        assertEquals("#", Solution.fold("#"));
        assertEquals("# | 5", Solution.fold(" # , 2, 3 "));
        assertEquals("3# | 2", Solution.fold("1#, 2#, 5, -3"));
        assertEquals("-1#", Solution.fold("-2#, #"));
        assertEquals("7", Solution.fold("2, +5"));
        assertEquals("0", Solution.fold("4, -4, 3#, -3#"));
        assertEquals("-2147483648", Solution.fold("-2147483648"));
        assertEquals("2147483647#", Solution.fold("2147483647#"));

        expectIllegalArgument(() -> Solution.fold(null));
        expectIllegalArgument(() -> Solution.fold(","));
        expectIllegalArgument(() -> Solution.fold("1,,2"));
        expectIllegalArgument(() -> Solution.fold("1,"));
        expectIllegalArgument(() -> Solution.fold(",1"));
        expectIllegalArgument(() -> Solution.fold("##"));
        expectIllegalArgument(() -> Solution.fold("1##"));
        expectIllegalArgument(() -> Solution.fold("+#"));
        expectIllegalArgument(() -> Solution.fold("-"));
        expectIllegalArgument(() -> Solution.fold("word"));
        expectIllegalArgument(() -> Solution.fold("2147483648"));

        expectArithmetic(() -> Solution.fold("2147483647,1"));
        expectArithmetic(() -> Solution.fold("-2147483648,-1"));
        expectArithmetic(() -> Solution.fold("2147483647#,1#"));
    }

    private static String nullSafeEmpty() {
        return "";
    }

    private static void assertEquals(String expected, String actual) {
        if (!expected.equals(actual)) {
            throw new AssertionError("expected <" + expected + "> but got <" + actual + ">");
        }
    }

    private static void expectIllegalArgument(Runnable action) {
        try {
            action.run();
            throw new AssertionError("expected IllegalArgumentException");
        } catch (IllegalArgumentException expected) {
            // expected
        }
    }

    private static void expectArithmetic(Runnable action) {
        try {
            action.run();
            throw new AssertionError("expected ArithmeticException");
        } catch (ArithmeticException expected) {
            // expected
        }
    }
}

